    # A missing uniform row in a horizontal stripe pattern takes the repeated stripe color.
    if all(len(set(row)) <= 1 for row in grid):
        out = [row[:] for row in grid]
        nonzero = [row[0] for row in grid if row[0] != 0]
        for r, row in enumerate(out):
