                out[r] = [nonzero[-1]] * w
        return out
    # Diagonal seeds specify colors by their c-r offset; extend their periodic sequence.
    cells = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                cells.setdefault((c-r) % 1, []).append((c-r, v))
    # Find the smallest period assigning a unique color to each observed residue.
    vals = [(c-r, v) for r,row in enumerate(grid) for c,v in enumerate(row) if v]
    period = next((p for p in range(2, 31) if all(len({v for d,v in vals if d%p==k}) <= 1 for k in range(p))), 1)
    seq = {}
    for d,v in vals:
        seq[d % period] = v
    # Fill any unobserved residues by cyclic interpolation when possible.
    for k in range(period):
        if k not in seq:
            seq[k] = seq[next(j for j in range(period) if j in seq)]
    return [[seq[(c-r)%period] for c in range(w)] for r in range(h)]
